mapper.select:
SELECT sc.status AS tabFlag, count(1) AS count FROM supplier_credential as sc WHERE sc.is_deleted=FALSE
${params.permissionSql}
GROUP BY sc.status order by sc.status

mapper.sql:
SELECT sc.ID AS ID, sc.create_user_id AS createUserId, sc.create_user_name AS createUserName, sc.create_time AS createTime, sc.update_user_id AS updateUserId, sc.update_user_name AS updateUserName, sc.update_time AS updateTime, sc.VERSION AS VERSION, sc.is_deleted AS isDeleted, sc.NAME AS NAME, sc.effective_date AS effectiveDate, sc.expire_date AS expireDate, sc.supplier_id AS supplierId, sc.remark AS remark, sc.code AS code, sc.status AS status, s.code AS supplierCode, s.NAME AS supplierName, s.approve_status AS supplierStatus FROM supplier_credential AS sc LEFT JOIN supplier AS s ON s.ID = sc.supplier_id AND s.is_deleted = FALSE WHERE ${params.sqlMap.default} AND sc.is_deleted = FALSE
and sc.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sc.create_time DESC
